import { MAP_SRC } from "@/lib/map-data";
import { cn } from "@/lib/utils";

export type MapPin = { slug: string; city: string; regionCode: string; locality: string; hub: boolean; x: number; y: number };

type Props = {
  pins: MapPin[];
  viewBox: { width: number; height: number };
  active?: string | null;
  className?: string;
  label?: string;
};

/**
 * Dot-matrix North America with glowing pins.
 *
 * The map is a static SVG file (generated by scripts/generate-map.ts), loaded lazily as an image so
 * its ~3,700 dots never sit in the page HTML or React payload, and painted once. Pins are HTML laid
 * over it at percentage positions, so their glow, pulsing ring (CSS, staggered) and hover scale
 * all run on the compositor instead of repainting thousands of SVG dots every frame. The active
 * pin grows and gets a label while the others dim. Pop-in is applied by <MapReveal> via
 * [data-pins]/[data-pin].
 */
export function LocationsMap({ pins, viewBox, active = null, className, label = "Map of Jnros locations across North America" }: Props) {
  return (
    <div data-pins="" role="img" aria-label={label} className={cn("relative", className)} style={{ aspectRatio: `${viewBox.width} / ${viewBox.height}` }}>
      {/* Plain <img>: static SVG artwork, nothing for next/image to optimize. */}
      <img data-map-dots src={MAP_SRC} alt="" width={viewBox.width} height={viewBox.height} loading="lazy" decoding="async" className="absolute inset-0 size-full" />
      <ul aria-hidden="true">
        {pins.map((pin, i) => {
          const isActive = active === pin.slug;
          const dim = active !== null && !isActive;
          return (
            <li
              key={pin.slug}
              className={cn("absolute transition-opacity duration-500", dim && "opacity-30", isActive && "z-10")}
              style={{ left: `${(pin.x / viewBox.width) * 100}%`, top: `${(pin.y / viewBox.height) * 100}%` }}
            >
              <span data-pin className="absolute left-0 top-0 block">
                <span
                  className={cn(
                    "absolute -translate-x-1/2 -translate-y-1/2 rounded-full bg-[radial-gradient(circle,rgb(122_193_67/0.5),transparent_68%)] transition-transform duration-500 ease-brand",
                    pin.hub ? "size-14" : "size-10",
                    isActive && "scale-150",
                  )}
                />
                <span
                  data-pulse
                  className={cn("absolute -translate-x-1/2 -translate-y-1/2 rounded-full border border-accent opacity-0 motion-safe:animate-pin-pulse", pin.hub ? "size-5" : "size-4")}
                  style={{ animationDelay: `${(i % 6) * 0.45}s` }}
                />
                <span
                  className={cn(
                    "absolute -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-bg transition-transform duration-500 ease-brand",
                    pin.hub ? "size-3.5" : "size-2.5",
                    isActive ? "scale-150 bg-accent-hover" : "bg-accent",
                  )}
                />
              </span>
              {isActive && (
                <span className="absolute bottom-4 left-0 -translate-x-1/2 whitespace-nowrap font-mono text-label uppercase text-text [text-shadow:0_1px_8px_rgb(0_0_0/0.9)]">
                  {pin.city}, {pin.regionCode}
                </span>
              )}
            </li>
          );
        })}
      </ul>
    </div>
  );
}
